 static IReadOnlyList<ToolDisplayObjectDefinition> LoadDisplay(){using var stream=typeof(TranslationPlugin).Assembly.GetManifestResourceStream("VisionPlugins.Calibration.Resources.TranslationCalibModuDisplay.xml")??throw new InvalidDataException("Missing Translation display resource.");using var reader=new StreamReader(stream);return ToolDisplayObjectDefinition.Parse(reader.ReadToEnd());}
 public ToolManifest Manifest{get;}=new(Id,"1.0.0","平移旋转标定","calibration","catalog/TranslationCalibModuImageEnable.png");
 static ParameterDescriptor P<T>(string name,ParameterKind kind,T value,double? min=null,double? max=null)=>new(name,kind,true,JsonSerializer.SerializeToElement(value),min,max);
 static ParameterDescriptor[] Parameters(){var list=new List<ParameterDescriptor>{P("CalibType",ParameterKind.Integer,0,0,1),P("CalibPointGet",ParameterKind.Integer,0,0,1),P("CalibPointInput",ParameterKind.Integer,0,0,1),P("CalibPointTotalNum",ParameterKind.Integer,9,4,16),P("RotPointTotalNum",ParameterKind.Integer,0,0,16),P("UnionCalibEnable",ParameterKind.Boolean,false),P("TeachEnable",ParameterKind.Boolean,false),P("RefreshFileEnable",ParameterKind.Boolean,false),P("CalibPathName",ParameterKind.Text,""),P("CameraMode",ParameterKind.Integer,1,1,3),P("HomoFreedom",ParameterKind.Integer,2,1,3),P("WeightFun",ParameterKind.Integer,3,1,3),P("WeightFactor",ParameterKind.Integer,20,1,200),P("DistThreshold",ParameterKind.Integer,30,1,100),P("SampleRatio",ParameterKind.Integer,60,1,100),P("ClearRevision",ParameterKind.Integer,0,0,int.MaxValue),P("ConfigurationUserData",ParameterKind.Text,"{}"),P("DisplayInputBindings",ParameterKind.Text,"{}"),P(ToolDisplayObjectStore.ParameterName,ParameterKind.Text,"{}")};for(int i=0;i<32;i++)foreach(string name in new[]{"ImagePointX","ImagePointY","WorldPointX","WorldPointY","DeltaAngle"})list.Add(P(name+i,ParameterKind.Number,0d));return list.ToArray();}
 public static readonly string[] IntegerOutputs=["ModuStatus","CalibStatus","CalibErrStatus","CalibCurIndex","CalibTotalNum","IsRightCoorA","RotDirectionState","TransErrMaxPtsNum","RotErrMaxPtsNum"];
 public static readonly string[] FloatOutputs=["TransError","RotError","RotCenterImageX","RotCenterImageY","RotCenterWorldX","RotCenterWorldY","TransEstMax","TransWorldError","TransErrWorldMax","RotErrMax","RotWorldError","RotErrWorldMax","Scale","DeltaX","DeltaY","Rotate","Tilt","DirectionRatio","PixelPrecision"];
 public static readonly string[] ArrayOutputs=["OutImagePointX","OutImagePointY","WorldPointX","WorldPointY"];
 public ModuleDescriptor Descriptor{get;}=new(Id,"1.0.0","平移旋转标定",new[]{"ImagePointX","ImagePointY","PhysicalPointX","PhysicalPointY","ImageRotateAngle","WorldRotateAngle"}.Select(n=>new PortDescriptor(n,DataKind.NumberArray,false){SupportsDeferredNumericRead=true}).Concat(new[]{new PortDescriptor("Image Point",DataKind.Point,false){Cardinality=ValueCardinality.Array},new("Physical Point",DataKind.Point,false){Cardinality=ValueCardinality.Array},new PortDescriptor("Trigger",DataKind.Text,false){SupportsDeferredTextRead=true},new("TeachFlag",DataKind.Text,false){SupportsDeferredTextRead=true},new(ToolDisplayService.PositionXInput,DataKind.Number,false,AcceptInteger:true),new(ToolDisplayService.PositionYInput,DataKind.Number,false,AcceptInteger:true)}).ToArray(),IntegerOutputs.Select(n=>new PortDescriptor(n,DataKind.Integer,false)).Concat(FloatOutputs.Concat(new[]{"ModuRunTime","WorldRotateAngle"}).Select(n=>new PortDescriptor(n,DataKind.Number,false))).Concat(ArrayOutputs.Select(n=>new PortDescriptor(n,DataKind.NumberArray,false))).Append(new("CalibData",DataKind.Calibration,false)).ToArray(),Parameters().Append(P(ToolDisplayService.SettingsParameter,ParameterKind.Text,"")).ToArray());
 public sealed class State {internal readonly object Gate=new();internal readonly float[,] Points=new float[32,6];internal readonly Dictionary<string,JsonElement> Applied=new();internal Dictionary<string,PortValue>? DisplayInputs,DisplayOutputs;internal int Current;internal int FileOrigin;internal int Direction=-999;internal NPointSolveResult? Result;internal bool HasTeach;internal float TeachX,TeachY,TeachAngle,SnapX,SnapY,SnapAngle;}
 readonly Dictionary<string,State> fallback=new();readonly object gate=new();
 State GetState(string node,string directory,ModuleExecutionScope? scope){if(scope is not null)return scope.State(Id,node,()=>new State());lock(gate){string key=Path.GetFullPath(directory)+"|"+node;if(!fallback.TryGetValue(key,out var value))fallback[key]=value=new();return value;}}
 public void Reset(string nodeId){lock(gate)foreach(string key in fallback.Keys.Where(k=>k.EndsWith("|"+nodeId,StringComparison.Ordinal)).ToArray())fallback.Remove(key);}
 public IModule CreateRuntime()=>new Runtime(this);
 public Form CreateEditor(ToolEditorContext context)=>throw new InvalidOperationException("Use WPF editor factory.");
 public System.Windows.Window CreateWpfEditor(ToolEditorContext context)=>new ToolConfigurationModelWindow(context,CreateConfiguration(context));
 public ToolConfigurationSession CreateConfiguration(ToolEditorContext context)=>new CalibrationToolConfigurationProvider(Id,"平移旋转标定",Descriptor,DisplayDefinition,"TranslationCalibModuAlgorithmTab.xml",UpdateConfiguration,Snapshot,Clear,Export,"TranslationCalibModuAlgorithm.xml").CreateConfiguration(context);
 static void ClearState(State state){for(int i=0;i<32;i++)for(int axis=0;axis<5;axis++)state.Points[i,axis]=0;state.Current=0;state.Result=null;state.HasTeach=false;state.TeachX=state.TeachY=state.TeachAngle=state.SnapX=state.SnapY=state.SnapAngle=0;}
 public void UpdateConfiguration(ToolEditorContext context,IReadOnlyDictionary<string,JsonElement> values){var state=GetState(context.Node.Id,context.BaseDirectory,context.Scope);lock(state.Gate)Synchronize(state,values);}
 static void Synchronize(State state,IReadOnlyDictionary<string,JsonElement> values){if(state.Applied.TryGetValue("ClearRevision",out var oldRevision)&&oldRevision.GetInt32()!=values["ClearRevision"].GetInt32()){ClearState(state);}for(int i=0;i<32;i++)for(int axis=0;axis<5;axis++){string key=new[]{"ImagePointX","ImagePointY","WorldPointX","WorldPointY","DeltaAngle"}[axis]+i;if(!state.Applied.TryGetValue(key,out var old)||old.GetRawText()!=values[key].GetRawText())state.Points[i,axis]=(float)values[key].GetDouble();}state.Applied.Clear();foreach(var pair in values)state.Applied[pair.Key]=pair.Value.Clone();}
 public float[,] Snapshot(ToolEditorContext c){var state=GetState(c.Node.Id,c.BaseDirectory,c.Scope);lock(state.Gate)return(float[,])state.Points.Clone();}
 public ToolAssetSnapshot PrepareSave(NodeDocument node,string directory,ResourceCatalog resources)=>new(node,[]);
 public ToolAssetSnapshot PrepareSave(NodeDocument node,string directory,ResourceCatalog resources,ModuleExecutionScope? scope){if(scope is null)return new(node,[]);var state=GetState(node.Id,directory,scope);lock(state.Gate){var parameters=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());if(state.Applied.Count==0)return new(node,[]);for(int i=0;i<32;i++)for(int axis=0;axis<5;axis++)parameters[new[]{"ImagePointX","ImagePointY","WorldPointX","WorldPointY","DeltaAngle"}[axis]+i]=JsonSerializer.SerializeToElement((double)state.Points[i,axis]);return new(node with{Parameters=parameters},[]);}}
 public void Clear(ToolEditorContext c){var state=GetState(c.Node.Id,c.BaseDirectory,c.Scope);lock(state.Gate){ClearState(state);}}
 public ToolDisplayFrame? LastDisplay(NodeDocument node,string baseDirectory,ModuleExecutionScope? scope){var state=GetState(node.Id,baseDirectory,scope);lock(state.Gate)return state.DisplayOutputs is null?null:ToolDisplayService.Build(DisplayDefinition,ToolDisplayService.Read(node.Parameters,DisplayDefinition),state.DisplayInputs??[],state.DisplayOutputs) with{Graphics=ToolDisplayGraphics.Build(DisplayObjectDefinitions,node.Parameters,state.DisplayInputs??[],state.DisplayOutputs)};}
 public void Export(ToolEditorContext c,string path){if(!Path.GetExtension(path).Equals(".xml",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("标定文件扩展名必须为.xml。");var state=GetState(c.Node.Id,c.BaseDirectory,c.Scope);lock(state.Gate){if(state.Result is null||state.Result.ErrorCode!=0||state.Current<c.Node.Parameters["CalibPointTotalNum"].GetInt32()+c.Node.Parameters["RotPointTotalNum"].GetInt32())throw new InvalidOperationException("尚无完整标定结果。");TranslationFile.Write(path,state.Points,state.Current,c.Node.Parameters,state.Result,state.HasTeach,new[]{state.SnapX,state.SnapY,state.SnapAngle,state.TeachX,state.TeachY,state.TeachAngle},state.FileOrigin);if(state.HasTeach)state.FileOrigin=(c.Node.Parameters["CalibPointTotalNum"].GetInt32()-1)/2;}}
 static float[] Input(ModuleExecutionContext c,string name){if(c.Inputs.TryGetValue(name,out var p))return p.Kind==DataKind.Number?[(float)p.As<double>()]:p.As<IReadOnlyList<double>>().Select(v=>(float)v).ToArray();string? combination=name switch{"ImagePointX" or "ImagePointY"=>"Image Point","PhysicalPointX" or "PhysicalPointY"=>"Physical Point",_=>null};if(combination is null||!c.Inputs.TryGetValue(combination,out var points))return [];bool x=name.EndsWith('X');return points.Cardinality==ValueCardinality.Array?points.As<IReadOnlyList<VisionCore.Point2>>().Select(point=>(float)(x?point.X:point.Y)).ToArray():[(float)(x?points.As<VisionCore.Point2>().X:points.As<VisionCore.Point2>().Y)];}
 static bool HasInput(ModuleExecutionContext c,string name)=>c.Inputs.ContainsKey(name)||c.Inputs.ContainsKey(name switch{"ImagePointX" or "ImagePointY"=>"Image Point","PhysicalPointX" or "PhysicalPointY"=>"Physical Point",_=>""});
 sealed class Runtime(TranslationPlugin owner):IModule {
  public ModuleDescriptor Descriptor=>owner.Descriptor;
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken token){token.ThrowIfCancellationRequested();var watch=Stopwatch.StartNew();var output=new Dictionary<string,PortValue>();var state=owner.GetState(c.NodeId,c.BaseDirectory,c.Scope);uint error=0;string? message=null;
   lock(state.Gate){
    int trans=c.Integer("CalibPointTotalNum"),rot=c.Integer("RotPointTotalNum"),total=trans+rot;bool manual=c.Integer("CalibPointGet")==1;
    foreach(var spec in Descriptor.Parameters){if(!c.Parameters.TryGetValue(spec.Name,out var value)||!GraphValidator.ValidParameter(spec,value)){error=0xe000030e;message="标定参数超出原厂范围。";break;}}
    if(error==0){
     Synchronize(state,c.Parameters);
     float[] ix=[],iy=[],wx=[],wy=[],ia=[],wa=[];
     bool teach=false;
     if(c.Boolean("TeachEnable")){
      var trigger=ReadTeachText(c,"Trigger");var flag=ReadTeachText(c,"TeachFlag");
      teach=flag.ErrorCode==0&&trigger.Count>0&&flag.Count>0&&trigger.Value.Split('\0')[0]==flag.Value.Split('\0')[0];
     }
     if(teach)error=ReadTeachingInputs(c,state,rot);
     else if(!manual&&state.Current<total)error=ReadCaptureInputs(c,rot,out ix,out iy,out wx,out wy,out ia,out wa);
     bool solve=false;
     if(error==0&&manual){state.Current=total;solve=true;}
     else if(error==0&&!teach&&state.Current<total){
      if(ix.Length!=iy.Length||wx.Length!=wy.Length)error=0xe0000001;
      else {int available=Math.Min(ix.Length,(state.Current<trans?trans:total)-state.Current);for(int k=0;k<available;k++){int index=state.Current++;state.Points[index,0]=ix[k];state.Points[index,1]=iy[k];if(k<wx.Length){state.Points[index,2]=wx[k];state.Points[index,3]=wy[k];}if(index<trans){state.Points[index,4]=rot>0&&k<wa.Length?wa[k]:0;state.Points[index,5]=rot>0&&k<ia.Length?ia[k]:0;}else{if(k<wa.Length)state.Points[index,4]=wa[k];if(k<ia.Length)state.Points[index,5]=ia[k];}}solve=state.Current==total;}
     }else if(error==0&&state.Current>=total){state.Current=total;solve=true;}
     if(error==0&&solve){token.ThrowIfCancellationRequested();var offsets=Enumerable.Range(0,trans).Select(i=>new NPointPair(state.Points[i,0],state.Points[i,1],state.Points[i,2],state.Points[i,3])).ToArray();var rotations=Enumerable.Range(trans,rot).Select(i=>new NPointRotation(state.Points[i,0],state.Points[i,1],state.Points[i,2],state.Points[i,3],state.Points[i,4])).ToArray();state.Result=TranslationSolve.Solve(offsets,rotations,c.Integer("CalibType"),c.Boolean("UnionCalibEnable"),new(c.Integer("HomoFreedom"),c.Integer("WeightFun"),c.Integer("CameraMode"),WeightFactor:c.Integer("WeightFactor"),DistThreshold:c.Integer("DistThreshold"),SampleRatio:c.Integer("SampleRatio")));error=state.Result.ErrorCode;if(error==0){if(rot>=3)state.Direction=NPointFile.RotationDirection(state.Points,trans,rot,c.Integer("CameraMode"))??state.Direction;state.Result=state.Result with{Direction=state.Direction};}
      if(error==0&&c.Boolean("RefreshFileEnable")&&!string.IsNullOrEmpty(c.Text("CalibPathName")))try{TranslationFile.Write(Path.GetFullPath(c.Text("CalibPathName"),c.BaseDirectory),state.Points,total,c.Parameters,state.Result,state.HasTeach,new[]{state.SnapX,state.SnapY,state.SnapAngle,state.TeachX,state.TeachY,state.TeachAngle},state.FileOrigin);if(state.HasTeach)state.FileOrigin=(trans-1)/2;}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or InvalidOperationException){/* Native ignores automatic refresh write failures. */}
     }
     if(error==0){output["ModuStatus"]=PortValue.Integer(1);output["CalibStatus"]=PortValue.Integer(solve?1:0);output["CalibCurIndex"]=PortValue.Integer(Math.Min(state.Current,total));output["CalibTotalNum"]=PortValue.Integer(total);for(int a=0;a<4;a++)output[ArrayOutputs[a]]=PortValue.Numbers(Enumerable.Range(0,Math.Min(state.Current,total)).Select(i=>(double)state.Points[i,a]));
      foreach(string name in IntegerOutputs.Except(new[]{"ModuStatus","CalibStatus","CalibCurIndex","CalibTotalNum","IsRightCoorA"}))output[name]=PortValue.Integer(0);foreach(string name in FloatOutputs.Where(n=>n!="Rotate"))output[name]=PortValue.Number(0);
      if(solve&&state.Result is {} result){Results(output,result);output.Remove("CalibErrStatus");output["IsRightCoorA"]=PortValue.Integer(TranslationSolve.RightCoordinate(result.Matrix));output["RotDirectionState"]=PortValue.Integer(state.Direction);}else output["WorldRotateAngle"]=PortValue.Number(0);
     }
    }
   }
   if(error==0)output["ModuRunTime"]=PortValue.Number(watch.Elapsed.TotalMilliseconds);lock(state.Gate){state.DisplayInputs=c.Inputs.ToDictionary(p=>p.Key,p=>p.Value);state.DisplayOutputs=output.ToDictionary(p=>p.Key,p=>p.Value);}return ValueTask.FromResult(new ModuleResult(error==0?ModuleStatus.Success:ModuleStatus.Failed,output,error==0?null:"TranslationCalibration",message){NativeErrorCode=error});
  }
 }
 static void Results(Dictionary<string,PortValue> output,NPointSolveResult r){foreach(var pair in new Dictionary<string,double>{{"TransError",r.OffsetError},{"RotError",r.RotateError},{"RotCenterImageX",r.CenterImageX},{"RotCenterImageY",r.CenterImageY},{"RotCenterWorldX",r.CenterWorldX},{"RotCenterWorldY",r.CenterWorldY},{"TransEstMax",r.OffsetMaxError},{"TransWorldError",r.OffsetWorldError},{"TransErrWorldMax",r.OffsetWorldMaxError},{"RotErrMax",r.RotateMaxError},{"RotWorldError",r.RotateWorldError},{"RotErrWorldMax",r.RotateWorldMaxError},{"Scale",r.Scale},{"DeltaX",r.DeltaX},{"DeltaY",r.DeltaY},{"Rotate",r.Theta},{"Tilt",r.Skew},{"DirectionRatio",r.Aspect},{"PixelPrecision",r.PixelPrecision}})output[pair.Key]=PortValue.Number((float)pair.Value);output["CalibErrStatus"]=PortValue.Integer(r.Status);output["RotDirectionState"]=PortValue.Integer(r.Direction);output["TransErrMaxPtsNum"]=PortValue.Integer(r.OffsetMaxErrorPointNum);output["RotErrMaxPtsNum"]=PortValue.Integer(r.RotateMaxErrorPointNum);output["CalibData"]=PortValue.Calibration(new(r.Matrix,Id));}
}
